  requireSafe(phases.includes(journal.phase) && typeof journal.at === 'string' && new Date(journal.at).toISOString() === journal.at && [null,'QUIESCENCE_NOT_PROVEN','COMMITTED_HOST_RESTORE_FAILED'].includes(journal.failureCode));
