    requireSafe(host?.NetworkMode === 'none' && host.ReadonlyRootfs === true && host.Privileged === false && same(host.CapDrop,['ALL']) && same(host.SecurityOpt,['no-new-privileges']));
    requireSafe(host.RestartPolicy?.Name==='no');
